async function buildGrandDesertStructure() {
    // Base and Foundation Coordinates
    const position = world.getPosition(bot);
    const startX = position.x;
    const startY = position.y;
    const startZ = position.z;
    const width = 20;
    const length = 20;
    const height = 10;

    // Create Foundation
    for (let x = startX; x <= startX + width; x++) {
        for (let z = startZ; z <= startZ + length; z++) {
            await skills.placeBlock(bot, 'sandstone', x, startY, z);
        }
    }

    // Create Pillars
    for (let x = startX; x <= startX + width; x += 2) {
        for (let z = startZ; z <= startZ + length; z += 2) {
            for (let y = startY + 1; y <= startY + height; y++) {
                await skills.placeBlock(bot, "chiseled_sandstone", x, y, z);
            }
        }
    }

    // Create Roof
    const roofY = startY + height + 1;
    for (let x = startX; x <= startX + width; x++) {
        for (let z = startZ; z <= startZ + length; z++) {
            await skills.placeBlock(bot, 'sandstone', x, roofY, z);
        }
    }

    // Add Natural Decorations
    const decorationItems = ["oak_leaves"];
    for (const item of decorationItems) {
        for (let x = 0; x < width / 2; x++) {
            for (let z = 0; z < length / 2; z++) {
                await skills.placeBlock(bot, item, startX + x * 4, startY + 1, startZ + z * 4);
            }
        }
    }
}

await buildGrandDesertStructure();

