// Function to place a rectangular foundation of sandstone
async function buildFoundation() {
    for (let x = startX; x < startX + 10; x++) {
        for (let z = startZ; z < startZ + 8; z++) {
            await skills.placeBlock(bot, "sandstone", x, startY, z);
        }
    }
}

// Function to build pillars on the corners
async function buildPillars() {
    // Define pillar height
    const pillarHeight = 6;

    const corners = [
        { x: startX, z: startZ },
        { x: startX + 9, z: startZ },
        { x: startX, z: startZ + 7 },
        { x: startX + 9, z: startZ + 7 }
    ];

    for (const corner of corners) {
        for (let y = startY + 1; y < startY + pillarHeight; y++) {
            await skills.placeBlock(bot, "chiseled_sandstone", corner.x, y, corner.z);
        }
    }
}

// Function to build walls of the home
async function buildWalls() {
    for (let x = startX + 1; x < startX + 9; x++) {
        for (let y = startY + 1; y < startY + 4; y++) {
            await skills.placeBlock(bot, "sandstone", x, y, startZ);
            await skills.placeBlock(bot, "sandstone", x, y, startZ + 7);
        }
    }

    for (let z = startZ + 1; z < startZ + 7; z++) {
        for (let y = startY + 1; y < startY + 4; y++) {
            await skills.placeBlock(bot, "sandstone", startX, y, z);
            await skills.placeBlock(bot, "sandstone", startX + 9, y, z);
        }
    }
}

// Function to add a roof to the home
async function buildRoof() {
    for (let x = startX; x < startX + 10; x++) {
        for (let z = startZ; z < startZ + 8; z++) {
            await skills.placeBlock(bot, "sandstone", x, startY + 4, z);
        }
    }
}

// Function to add windows
async function addWindows() {
    await skills.breakBlockAt(bot, startX + 4, startY + 2, startZ);
    await skills.breakBlockAt(bot, startX + 5, startY + 2, startZ);
    await skills.placeBlock(bot, "glass", startX + 4, startY + 2, startZ);
    await skills.placeBlock(bot, "glass", startX + 5, startY + 2, startZ);

    await skills.breakBlockAt(bot, startX + 4, startY + 2, startZ + 7);
    await skills.breakBlockAt(bot, startX + 5, startY + 2, startZ + 7);
    await skills.placeBlock(bot, "glass", startX + 4, startY + 2, startZ + 7);
    await skills.placeBlock(bot, "glass", startX + 5, startY + 2, startZ + 7);
}

// Function to add a door
async function addDoor() {
    await skills.breakBlockAt(bot, startX + 4, startY + 1, startZ);
    await skills.breakBlockAt(bot, startX + 5, startY + 1, startZ);
    await skills.placeBlock(bot, "oak_door", startX + 4, startY + 1, startZ);
}

// Main function to build the house
async function buildHouse() {
    await buildFoundation();
    await buildPillars();
    await buildWalls();
    await buildRoof();
    await addWindows();
    await addDoor();
}

