async function buildWoodenHouse() {
    let inventory = world.getInventoryCounts(bot);

    // Check if there are enough wooden planks.
    let woodenPlanks = inventory['oak_planks'] || 0;

    // If not enough planks, collect additional logs and craft them into planks.
    if (woodenPlanks < 100) {
        await skills.collectBlock(bot, 'oak_log', 10);
        await skills.craftRecipe(bot, 'oak_planks');
    }

    // Refresh inventory counts
    inventory = world.getInventoryCounts(bot);
    woodenPlanks = inventory['oak_planks'] || 0;

    if (woodenPlanks < 100) {
        log(bot,'Not enough wooden planks even after collecting logs.');
        return;
    }

    // Coordinates for house base relative to bot's position
    let baseX = botPosition.x + 1;
    let baseY = botPosition.y;
    let baseZ = botPosition.z + 1;

    // Build the house base (5x5)
    for (let x = 0; x < 5; x++) {
        for (let z = 0; z < 5; z++) {
            await skills.placeBlock(bot, 'oak_planks', baseX + x, baseY, baseZ + z);
        }
    }

    // Build the walls (3 blocks high)
    for (let y = 1; y <= 3; y++) {
        for (let x = 0; x < 5; x++) {
            await skills.placeBlock(bot, 'oak_planks', baseX + x, baseY + y, baseZ);
            await skills.placeBlock(bot, 'oak_planks', baseX + x, baseY + y, baseZ + 4);
        }
        for (let z = 1; z < 4; z++) {
            await skills.placeBlock(bot, 'oak_planks', baseX, baseY + y, baseZ + z);
            await skills.placeBlock(bot, 'oak_planks', baseX + 4, baseY + y, baseZ + z);
        }
    }

    // Craft a door
    await skills.craftRecipe(bot, 'oak_door');

    // Add a door
    await skills.placeBlock(bot, 'oak_door', baseX + 2, baseY + 1, baseZ);

    // Build the roof (pyramid-shaped)
    for (let layer = 0; layer < 5; layer++) {
        for (let x = layer; x < 5 - layer; x++) {
            for (let z = layer; z < 5 - layer; z++) {
                await skills.placeBlock(bot, 'oak_planks', baseX + x, baseY + 4 + layer, baseZ + z);
            }
        }
    }

    log(bot,'Wooden house with a nice roof built successfully.');
}

