    foundCave = await searchForCave();
    if (foundCave) break;

    // If no cave found, move 16 blocks in a random direction
    let angle = Math.random() * 2 * Math.PI;
    let newX = position.x + Math.round(16 * Math.cos(angle));
    let newZ = position.z + Math.round(16 * Math.sin(angle));
    await skills.goToPosition(bot, newX, position.y, newZ);
    position = world.getPosition(bot);
}

if (foundCave) {
    log(bot, "Found a cave!");
